-- H5 metadata only; no application rows or function bodies are returned.
select jsonb_build_object(
 'tables',(select coalesce(jsonb_agg(jsonb_build_array(n.nspname,c.relname,c.relkind,c.relrowsecurity,c.relforcerowsecurity) order by n.nspname,c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','ai_internal','guardian_internal') and c.relkind in ('r','p','v','m','S')),
 'columns',(select coalesce(jsonb_agg(jsonb_build_array(table_schema,table_name,column_name,data_type,udt_name,is_nullable,column_default,is_identity,identity_generation) order by table_schema,table_name,ordinal_position),'[]') from information_schema.columns where table_schema in ('public','ai_internal','guardian_internal')),
 'policies',(select coalesce(jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname),'[]') from pg_policies p where schemaname in ('public','ai_internal','guardian_internal')),
 'constraints',(select coalesce(jsonb_agg(jsonb_build_array(n.nspname,c.relname,k.conname,pg_get_constraintdef(k.oid)) order by n.nspname,c.relname,k.conname),'[]') from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','ai_internal','guardian_internal')),
 'indexes',(select coalesce(jsonb_agg(jsonb_build_array(schemaname,tablename,indexname,indexdef) order by schemaname,tablename,indexname),'[]') from pg_indexes where schemaname in ('public','ai_internal','guardian_internal')),
 'triggers',(select coalesce(jsonb_agg(jsonb_build_array(n.nspname,c.relname,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid)) order by n.nspname,c.relname,t.tgname),'[]') from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and (n.nspname in ('public','ai_internal','guardian_internal') or (n.nspname='auth' and c.relname='users'))),
 'functions',(select coalesce(jsonb_agg(jsonb_build_array(n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),p.prosecdef,p.proconfig,md5(pg_get_functiondef(p.oid))) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','ai_internal','guardian_internal') and p.prokind in ('f','p')),
 'table_grants',(select coalesce(jsonb_agg(jsonb_build_array(table_schema,table_name,grantee,privilege_type) order by table_schema,table_name,grantee,privilege_type),'[]') from information_schema.table_privileges where table_schema in ('public','ai_internal','guardian_internal') and grantee in ('anon','authenticated','PUBLIC','service_role')),
 'routine_grants',(select coalesce(jsonb_agg(jsonb_build_array(routine_schema,routine_name,grantee,privilege_type) order by routine_schema,routine_name,grantee,privilege_type),'[]') from information_schema.routine_privileges where routine_schema in ('public','ai_internal','guardian_internal') and grantee in ('anon','authenticated','PUBLIC','service_role')),
 'schema_access',(select coalesce(jsonb_agg(jsonb_build_array(n.nspname,r.rolname,has_schema_privilege(r.rolname,n.oid,'USAGE'),has_schema_privilege(r.rolname,n.oid,'CREATE')) order by n.nspname,r.rolname),'[]') from pg_namespace n cross join pg_roles r where n.nspname in ('public','ai_internal','guardian_internal') and r.rolname in ('anon','authenticated','service_role'))
) as inventory;
